const tel=p=>{const parts=p.split(/\s+ext\.?\s*/i);return 'tel:'+parts[0].replace(/[^+0-9]/g,'')+(parts[1]?';ext='+parts[1].replace(/\D/g,''):'')};
const phoneLink=p=>p?'<a class="phone" href="'+esc(tel(p))+'">'+esc(p)+'</a>':'';
